create table if not exists public.maintenance_training (id text primary key,type text not null default 'training' check(type in('training','procedure','checklist')),title text not null,description text not null default '',machine text,category text not null default 'Geral',audience text not null default 'Todos da manutenção',frequency text not null default 'Quando necessário',responsible text not null default '',material_url text,steps text not null default '',status text not null default 'active' check(status in('draft','active','review','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.maintenance_training_progress(id text primary key,training_id text not null references public.maintenance_training(id) on delete cascade,mechanic text not null,mechanic_label text not null default '',status text not null default 'completed',score numeric,notes text not null default '',completed_at timestamptz not null default now());create index if not exists idx_training_machine on public.maintenance_training(machine);create index if not exists idx_training_status on public.maintenance_training(status);create index if not exists idx_training_progress_training on public.maintenance_training_progress(training_id);create index if not exists idx_training_progress_mechanic on public.maintenance_training_progress(mechanic);alter table public.maintenance_training enable row level security;alter table public.maintenance_training_progress enable row level security;